import val from "./val/index.js";
import { star } from "./star/index.js";

export default function style() {
	const fn = () => 1;
	// the sole references are dropped by DCE, so nothing requests these names
	// from the barrels and their re-export targets stay deferred
	fn.propTypes =
		process.env.NODE_ENV !== "production" ? { val, star } : {};
	return fn;
}
